-- Study Hub — initial schema
-- IDs are UUID strings generated by the app. Timestamps are ISO-8601 UTC strings.
-- `position` is a REAL so items can be reordered by inserting between two neighbours.

CREATE TABLE semesters (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  position    REAL NOT NULL,
  collapsed   INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE courses (
  id          TEXT PRIMARY KEY,
  semester_id TEXT NOT NULL REFERENCES semesters(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  color       TEXT NOT NULL,
  position    REAL NOT NULL,
  collapsed   INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_courses_semester ON courses(semester_id);

-- Imported PDFs. The file itself lives in the app's data folder at `stored_path`.
CREATE TABLE documents (
  id          TEXT PRIMARY KEY,
  course_id   TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  title       TEXT NOT NULL,
  file_name   TEXT NOT NULL,
  stored_path TEXT NOT NULL,
  page_count  INTEGER,
  sha256      TEXT,
  position    REAL NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_documents_course ON documents(course_id);

-- Notes. `content` is the block editor's JSON; `plain_text` is derived from it for search and export.
-- `document_id` is the PDF shown next to this note in split view.
CREATE TABLE pages (
  id          TEXT PRIMARY KEY,
  course_id   TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  document_id TEXT REFERENCES documents(id) ON DELETE SET NULL,
  title       TEXT NOT NULL DEFAULT '',
  content     TEXT NOT NULL DEFAULT '[]',
  plain_text  TEXT NOT NULL DEFAULT '',
  position    REAL NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_pages_course ON pages(course_id);

-- PDF highlights. `rects` is JSON: [{ "x", "y", "w", "h" }] in page-relative units (0..1).
CREATE TABLE highlights (
  id          TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  page_number INTEGER NOT NULL,
  rects       TEXT NOT NULL,
  color       TEXT NOT NULL CHECK (color IN ('yellow', 'blue', 'green')),
  text        TEXT NOT NULL DEFAULT '',
  comment     TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_highlights_document ON highlights(document_id, page_number);

-- Cropped regions of a PDF page, stored as an image in the app's data folder.
CREATE TABLE snips (
  id          TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  page_number INTEGER NOT NULL,
  rect        TEXT NOT NULL,
  image_path  TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_snips_document ON snips(document_id);

-- Which note block points at which highlight or snip (drives "In note" chips and "Jump to page").
CREATE TABLE note_refs (
  page_id      TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
  block_id     TEXT NOT NULL,
  highlight_id TEXT REFERENCES highlights(id) ON DELETE CASCADE,
  snip_id      TEXT REFERENCES snips(id) ON DELETE CASCADE,
  PRIMARY KEY (page_id, block_id),
  CHECK ((highlight_id IS NULL) <> (snip_id IS NULL))
);
CREATE INDEX idx_note_refs_highlight ON note_refs(highlight_id);
CREATE INDEX idx_note_refs_snip ON note_refs(snip_id);

CREATE TABLE tags (
  id    TEXT PRIMARY KEY,
  name  TEXT NOT NULL UNIQUE COLLATE NOCASE
);

CREATE TABLE page_tags (
  page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
  tag_id  TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (page_id, tag_id)
);
CREATE INDEX idx_page_tags_tag ON page_tags(tag_id);

-- Small key/value store for UI state (last open page, view mode, ...).
CREATE TABLE kv (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

-- Full-text search over notes. Kept in sync by triggers.
CREATE VIRTUAL TABLE pages_fts USING fts5(
  page_id UNINDEXED,
  title,
  plain_text,
  tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER pages_fts_insert AFTER INSERT ON pages BEGIN
  INSERT INTO pages_fts (page_id, title, plain_text) VALUES (new.id, new.title, new.plain_text);
END;

CREATE TRIGGER pages_fts_delete AFTER DELETE ON pages BEGIN
  DELETE FROM pages_fts WHERE page_id = old.id;
END;

CREATE TRIGGER pages_fts_update AFTER UPDATE OF title, plain_text ON pages BEGIN
  DELETE FROM pages_fts WHERE page_id = old.id;
  INSERT INTO pages_fts (page_id, title, plain_text) VALUES (new.id, new.title, new.plain_text);
END;
